package domain

import "time"

// WorkflowAsset tracks intermediate files generated by workflow nodes.
// Used for cleanup when nodes are deleted or workflows are purged.
type WorkflowAsset struct {
	ID         string
	WorkflowID string
	NodeID     string
	AssetPath  string
	AssetType  string
	SizeBytes  int64
	CreatedAt  time.Time
}

// WorkflowAssetModel is the GORM model backing the workflow_assets table.
type WorkflowAssetModel struct {
	ID         string    `gorm:"column:id;primaryKey"`
	WorkflowID string    `gorm:"column:workflow_id;not null;index:workflow_assets_workflow_idx"`
	NodeID     string    `gorm:"column:node_id;not null;index:workflow_assets_node_idx"`
	AssetPath  string    `gorm:"column:asset_path;not null"`
	AssetType  string    `gorm:"column:asset_type;not null"`
	SizeBytes  int64     `gorm:"column:size_bytes;not null;default:0"`
	CreatedAt  time.Time `gorm:"column:created_at;not null;autoCreateTime:nano"`

	Workflow WorkflowModel `gorm:"foreignKey:WorkflowID;references:ID;constraint:OnDelete:CASCADE"`
}

// TableName returns the backing table name.
func (WorkflowAssetModel) TableName() string {
	return "workflow_assets"
}
